using System;using System.Text;
class Program{static string D(string x){if(x=="~")return null;var s=new StringBuilder();if(x!="-")for(int i=0;i<x.Length;i+=4)s.Append((char)Convert.ToInt32(x.Substring(i,4),16));return s.ToString();}static string H(string s){if(s==null)return "~";if(s.Length==0)return "-";var b=new StringBuilder();foreach(var c in s)b.Append(((int)c).ToString("x4"));return b.ToString();}static void Main(){string line;while((line=Console.ReadLine())!=null){var p=line.Split(' ');try{var text=D(p[1]);var uri=text==null?null:new Uri(text,UriKind.RelativeOrAbsolute);var result=p[0]=="N"?new Uri(uri,(Uri)null):new Uri(uri,(string)null);Console.WriteLine(H(result.OriginalString)+"/"+H(result.AbsoluteUri)+"/"+H(result.ToString()));}catch(Exception e){Console.WriteLine(e.GetType().FullName+":"+unchecked((uint)e.HResult).ToString("x8")+":"+H(e.Message)+":"+(e is ArgumentException a?H(a.ParamName):"~"));}}}}
